package com.genchat.controller;
import com.genchat.dto.MessageRequest; import com.genchat.model.Message; import com.genchat.service.MessageService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/messages") public class MessageController { private final MessageService service; public MessageController(MessageService service){this.service=service;} @GetMapping public List<Message> all(){return service.all();} @PostMapping public ResponseEntity<Message> send(@Valid @RequestBody MessageRequest r, Authentication auth){return ResponseEntity.status(HttpStatus.CREATED).body(service.send(auth.getName(),r.content()));} }
